-- Bundled comparison fixture for the asb-detection-compare GitHub Action.
--
-- Auto-generated by scripts/build-fixture.php from a real corpus, stratified
-- by antispam_bee_reason + comment_type (<=10 rows each). PII removed: author,
-- e-mail and IP are synthetic for every row, comment IDs are renumbered from 1
-- (original IDs discarded), and ham content is synthetic; spam content/URLs are
-- kept because the rules act on them. Do not edit by hand.
-- Rows: 122.
--
-- Groups (source antispam_bee_reason; up to 10 rows each):
--   (ham)           24  comment ×10, pingback ×10, trackback ×4 legitimate comments (content synthesized; envelope anonymized)
--   css             10  comment ×10           honeypot / CSS decoy catch (content replayed via the visible field)
--   empty           10  comment ×10           empty comment body
--   localdb         28  comment ×10, pingback ×9, trackback ×9 local-DB spam (IP / e-mail / URL seen before)
--   manually        30  comment ×10, pingback ×10, trackback ×10 manually marked as spam
--   regexp          10  comment ×10           matched a spam regex pattern
--   title_is_name   10  trackback ×10         linkback title equals the blog name

DROP TABLE IF EXISTS wp_comments;
CREATE TABLE wp_comments (
	comment_ID           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
	comment_content      TEXT,
	comment_author       TINYTEXT,
	comment_author_email VARCHAR(100) DEFAULT '',
	comment_author_url   VARCHAR(200) DEFAULT '',
	comment_author_IP    VARCHAR(100) DEFAULT '',
	comment_agent        VARCHAR(255) DEFAULT '',
	comment_type         VARCHAR(20)  DEFAULT 'comment',
	PRIMARY KEY (comment_ID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS wp_commentmeta;
CREATE TABLE wp_commentmeta (
	meta_id    BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
	comment_id BIGINT UNSIGNED NOT NULL DEFAULT 0,
	meta_key   VARCHAR(255) DEFAULT NULL,
	meta_value LONGTEXT,
	PRIMARY KEY (meta_id),
	KEY comment_id (comment_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

